# -*- coding: utf-8 -*-
"""
VoiceHire — Centralized Multilingual Translation & Indian Localization Layer
═══════════════════════════════════════════════════════════════════════════════
Architectural Rules:
 1. Centralized translations for UI, assistant, statuses, validation, and errors.
 2. Hindi ('hi') is the platform default; Punjabi ('pa') and English ('en') are
    Tier 1 Verified languages with 100% key parity and verified STT/TTS.
 3. Native Indian localization: Currency (₹ lakhs/crores formatting), Indian dates,
    numbers, and status transparency (never rely on color/icons alone).
 4. Safe fallbacks: unknown languages fall back to Hindi ('hi') gracefully.
═══════════════════════════════════════════════════════════════════════════════
"""

